import Link from "next/link";
import { usePathname } from "next/navigation";
import type { ComponentProps } from "react";
import { classifyNavigation, shouldInterceptNavigation } from "./classify-navigation";
import type { SiteNavItem } from "./navigation-types";
import { useRouteTransition } from "./use-route-transition";

export type TransitionLinkProps = ComponentProps<typeof Link> & {
  href: string;
};

export function TransitionLink({
  href,
  onClick,
  target,
  download,
  className,
  children,
  ...props
}: TransitionLinkProps) {
  const pathname = usePathname();
  const transition = useRouteTransition();
  const hrefValue = href;

  return (
    <Link
      href={href}
      target={target}
      download={download}
      className={className}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) {
          return;
        }
        const kind = classifyNavigation({
          href: hrefValue,
          currentPathname: pathname,
          target: typeof target === "string" ? target : undefined,
          download: Boolean(download),
          metaKey: event.metaKey,
          ctrlKey: event.ctrlKey,
          shiftKey: event.shiftKey,
          altKey: event.altKey,
          button: event.button,
        });
        if (!shouldInterceptNavigation(kind)) {
          return;
        }
        if (transition.reducedMotion) {
          event.preventDefault();
          transition.navigate(hrefValue);
          return;
        }
        if (!transition.enabled) {
          return;
        }
        event.preventDefault();
        transition.navigate(hrefValue);
      }}
      {...props}
    >
      {children}
    </Link>
  );
}

export function DesktopNavigation({
  items,
  className,
}: {
  items: SiteNavItem[];
  className?: string;
}) {
  const pathname = usePathname();
  return (
    <nav aria-label="Primary" className={cn("hidden min-w-0 md:block", className)}>
      <ul className="flex flex-nowrap items-center gap-6 overflow-x-auto">
        {items.map((item) => {
          const current = pathname === item.href;
          return (
            <li key={item.href} className="shrink-0">
              <TransitionLink
                href={item.href}
                aria-current={current ? "page" : undefined}
                className={cn(
                  "whitespace-nowrap text-sm",
                  current ? "text-foreground" : "text-foreground/70",
                )}
              >
                {item.label}
              </TransitionLink>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

export type SiteNavItem = {
  href: string;
  label: string;
};

export type NavigationKind =
  | "internal"
  | "hash"
  | "external"
  | "download"
  | "new-tab"
  | "modified";

export type ClassifyNavigationInput = {
  href: string;
  currentPathname: string;
  target?: string | null;
  download?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  shiftKey?: boolean;
  altKey?: boolean;
  button?: number;
};

export function classifyNavigation(input: ClassifyNavigationInput): NavigationKind {
  if (input.button != null && input.button !== 0) {
    return "modified";
  }
  if (input.metaKey || input.ctrlKey || input.shiftKey || input.altKey) {
    return "modified";
  }
  if (input.download) {
    return "download";
  }
  if (input.target === "_blank") {
    return "new-tab";
  }

  const href = input.href.trim();
  if (!href || href === "#") {
    return "hash";
  }
  if (
    href.startsWith("mailto:") ||
    href.startsWith("tel:") ||
    href.startsWith("sms:")
  ) {
    return "external";
  }

  if (href.startsWith("//")) {
    return "external";
  }
  try {
    const url = new URL(href, "http://cds.local");
    if (url.protocol === "http:" || url.protocol === "https:") {
      const isAbsolute = /^https?:\/\//i.test(href);
      if (isAbsolute) {
        return "external";
      }
    }
    if (href.startsWith("#") || (url.pathname === input.currentPathname && url.hash)) {
      return "hash";
    }
    return "internal";
  } catch {
    return "external";
  }
}

export function shouldInterceptNavigation(kind: NavigationKind): boolean {
  return kind === "internal";
}

"use client";

import { createContext, useContext } from "react";
import type { RouteTransitionState } from "./route-transition-types";

export type RouteTransitionApi = RouteTransitionState & {
  navigate: (href: string) => void;
  fail: () => void;
};

export const RouteTransitionContext = createContext<RouteTransitionApi | null>(null);

export function useRouteTransition(): RouteTransitionApi {
  const value = useContext(RouteTransitionContext);
  if (!value) {
    return {
      phase: "idle",
      href: null,
      enabled: false,
      reducedMotion: false,
      navigate: (href: string) => {
        window.location.assign(href);
      },
      fail: () => undefined,
    };
  }
  return value;
}

import type { ReactNode } from "react";

export type RouteTransitionPhase = "idle" | "covering" | "waiting" | "revealing";

export type RouteTransitionState = {
  phase: RouteTransitionPhase;
  href: string | null;
  enabled: boolean;
  reducedMotion: boolean;
};

export type RouteTransitionRenderOverlay = (state: RouteTransitionState) => ReactNode;

export const ROUTE_TRANSITION_TIMEOUT_MS = 8000;
export const ROUTE_TRANSITION_COVER_MS = 280;
export const MAIN_CONTENT_ID = "main-content";
